WITH with_last AS (SELECT s.id, s.customer_id, s.account_type, s.balance, s.opened_date, s.status, x.transaction_amount FROM accounts s JOIN LATERAL (SELECT c.amount AS transaction_amount FROM transactions c WHERE c.account_id = s.id AND c.txn_time <= s.opened_date ORDER BY c.txn_time DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT DATE_TRUNC('YEAR', opened_date) AS year_start, APPROX_PERCENTILE(transaction_amount, 0.9) AS transaction_amount_p90, PERCENTILE_APPROX(transaction_amount, ARRAY(0.25, 0.5, 0.75)) AS transaction_amount_quartiles, COUNT(CASE WHEN status = 'CLOSED' THEN 1 END) AS closed_count FROM with_last GROUP BY 1
